import json
from pathlib import Path
M=json.loads(Path('reports/_work/methods.json').read_text())
F=[]
def add(group,title,key,controller,front,entities,goal,inputs,pre,steps,condition,error,post,note='',status='Đã xác minh mã nguồn'):
 if key not in M:raise ValueError(key)
 r=max(M[key],key=lambda r:len(r['code']))
 F.append(dict(group=group,title=title,key=key,controller=controller,front=front,entities=entities,goal=goal,inputs=inputs,pre=pre,steps=steps.split(' | '),condition=condition,error=error,post=post,note=note,status=status,source=r))
C='Khách hàng';T='Thu ngân';K='Nhân viên bếp';A='Quản trị viên';V='Vai trò cơ sở và phân hệ mở rộng'
login='templates/auth/login.html';cart='templates/customer/cart.html; static/js/customer/customer.js';orders='templates/customer/orders.html; static/js/order/orders.js';cash='templates/cashier/index.html; static/js/cashier/cashier.js';kitchen='templates/kitchen/orders.html; static/js/kitchen/kitchen.js';inv='templates/admin/inventory.html; static/js/admin/admin.js';portal='templates/market/portal.html; static/js/market/portal.js'
add(C,'Đăng ký tài khoản chờ xác thực','AuthService.register','AuthController',login,'Account; EmailVerificationOtp','Tạo hồ sơ khách hàng có email chưa xác thực, chuẩn bị OTP để kích hoạt tài khoản.','Email, mật khẩu, họ tên, số điện thoại 10 chữ số.','Chưa đăng nhập; thông tin phải thỏa AuthDto.RegisterRequest; cấu hình OTP/SMTP hợp lệ.','Chuẩn hóa email và khóa tài khoản trùng email | Từ chối email đã xác thực; chỉ tái sử dụng CUSTOMER chưa xác thực còn hoạt động | BCrypt mật khẩu và lưu emailVerified=false | Sinh OTP HMAC, lưu thời hạn và đăng ký gửi thư sau commit | Trả email che bớt và thời gian chờ gửi lại','Email có được phép đăng ký?','Email đã dùng, tài khoản bị khóa, DTO sai, thiếu khóa OTP hoặc SMTP lỗi.','Không cấp JWT trước xác thực. SMTP thất bại vẫn giữ tài khoản pending sau commit để có thể gửi lại.','Role CUSTOMER được gán ở server; client không được tự nâng quyền. Mật khẩu và OTP thô không trả trong response.')
add(C,'Xác thực email bằng OTP','AuthService.verifyEmail','AuthController',login,'Account; EmailVerificationOtp','Kích hoạt email sau khi người dùng chứng minh quyền sở hữu hộp thư.','Email và OTP gồm đúng 6 chữ số.','Tài khoản đã được tạo; mã chưa dùng, chưa thu hồi và còn thời hạn.','Tìm tài khoản theo email chuẩn hóa | Nếu đã xác thực thì trả thông báo tương ứng | Kiểm tra OTP theo purpose REGISTER_VERIFY | Ghi emailVerified=true và lưu tài khoản | Cho phép sử dụng chức năng đăng nhập','OTP khớp và còn hiệu lực?','Mã sai, hết hạn, bị khóa sau giới hạn thử hoặc không có tài khoản.','OTP đúng được đánh dấu usedAt; trạng thái active do quản trị khóa không tự mở lại.','noRollbackFor với lỗi nghiệp vụ giữ số lần nhập sai/thu hồi mã trong DB; không suy diễn mã hóa HMAC thành mã hóa có thể giải ngược.')
add(C,'Gửi lại mã xác thực đăng ký','AuthService.resendRegisterOtp','AuthController',login,'Account; EmailVerificationOtp','Cho phép khôi phục quy trình kích hoạt khi chưa nhận được email hoặc OTP đã hết hạn.','Email đã đăng ký.','Tài khoản chưa emailVerified; đã qua cooldown mặc định 60 giây.','Khóa tài khoản theo email | Kiểm tra trạng thái chưa xác thực | Kiểm tra lần gửi mới nhất, kể cả mã đã thu hồi | Thu hồi mã cũ và tạo OTP mới | Gửi thư sau commit và trả thông báo email được che','Đã hết cooldown và chưa xác thực?','Gửi dồn dập, email không tồn tại, email đã xác thực, SMTP chưa hoạt động.','Chỉ OTP mới nhất còn khả năng xác thực, mã trước không được tiếp tục sử dụng.','Giao diện có đồng hồ chờ; giới hạn thật được kiểm tra lại ở server, không dựa vào nút disabled của trình duyệt.')
add(C,'Đăng nhập theo trạng thái tài khoản','AuthService.login','AuthController',login,'Account','Xác thực thông tin đăng nhập và tạo phiên JWT theo vai trò.','Email và mật khẩu.','Tài khoản tồn tại, active=true, emailVerified=true.','Chuẩn hóa email và tìm Account | Kiểm tra khóa quản trị | So khớp mật khẩu bằng PasswordEncoder | Từ chối email chưa xác thực | Sinh JWT và trả UserInfo','Thông tin, active và emailVerified hợp lệ?','Sai thông tin, tài khoản tạm khóa hoặc chưa xác thực email.','Controller lưu JWT vào cookie HttpOnly; CSRF được cấp lại sau đăng nhập.','JWT mang tokenVersion; filter đối chiếu lại trạng thái tài khoản và phiên bản để vô hiệu token cũ.')
add(C,'Đăng xuất và vô hiệu phiên','AuthService.logout','AuthController',login,'Account','Kết thúc sử dụng tài khoản và giảm khả năng tái sử dụng token cũ.','Tác nhân hiện tại từ JWT cookie; CSRF cho POST logout.','Có cookie hoặc ngữ cảnh tài khoản của phiên hiện tại.','Lấy accountId từ CurrentActor | Tăng tokenVersion của tài khoản khi có | Controller xóa cookie đăng nhập | Xóa CSRF cũ để nhận phiên truy cập mới','Có tài khoản cần vô hiệu?','Thiếu CSRF hoặc token không còn hợp lệ sẽ đi qua chính sách bảo mật chung.','Trình duyệt không tiếp tục dùng cookie cũ; tokenVersion cũ bị filter từ chối.','Đăng xuất không tự đóng phiên bàn và không xóa chứng từ đơn hàng.')
add(C,'Yêu cầu khôi phục mật khẩu qua email','AuthService.requestPasswordReset','AuthController',login,'Account; EmailVerificationOtp','Khởi tạo quy trình lấy lại quyền truy cập khi quên mật khẩu.','Email cần khôi phục.','Cấu hình mail/OTP hợp lệ; địa chỉ phải đúng định dạng.','Chuẩn hóa email | Trả thông báo chung nếu không tồn tại | Sinh OTP mục đích PASSWORD_RESET, hạn 15 phút | Gửi thư qua MailService | Trả thông báo không chứa mã','Tài khoản có tồn tại?','Cooldown hoặc SMTP không gửi được; phản hồi không công khai OTP.','Chưa thay đổi mật khẩu ở bước yêu cầu.','Thông báo chung hạn chế tiết lộ tài khoản. Không mô tả bước này là đặt lại mật khẩu thành công.')
add(C,'Xác minh OTP khôi phục và nhận vé tạm','AuthService.verifyPasswordResetOtp','AuthController',login,'Account; EmailVerificationOtp; PasswordResetToken','Tách bước kiểm tra OTP khỏi bước nhập mật khẩu mới.','Email và OTP khôi phục.','Tài khoản còn hoạt động; OTP đúng purpose và chưa được dùng.','Kiểm tra email và trạng thái tài khoản | Xác minh OTP PASSWORD_RESET | Sinh chuỗi resetToken ngẫu nhiên | Lưu hash của vé tạm và thời hạn | Trả vé tạm cho bước xác nhận mật khẩu','OTP khôi phục hợp lệ?','Sai OTP, hết hạn, vượt số lần thử hoặc tài khoản khóa.','Mã OTP bị tiêu thụ; vé tạm có hạn dùng để xác nhận bước tiếp theo.','Vé reset chỉ dành cho luồng quên mật khẩu, không phải JWT đăng nhập.')
add(C,'Xác nhận mật khẩu mới','AuthService.confirmPasswordReset','AuthController',login,'Account; PasswordResetToken; EmailVerificationOtp','Cập nhật mật khẩu sau khi người dùng hoàn thành bằng chứng khôi phục.','Email, resetToken hoặc mã theo nhánh tương thích và newPassword.','Vé tạm/chứng cứ khôi phục đúng tài khoản, chưa dùng và còn hạn.','Kiểm tra thông tin yêu cầu | Tìm và xác minh token hash hoặc nhánh OTP tương thích | BCrypt mật khẩu mới | Đánh dấu vé đã dùng và tăng tokenVersion | Lưu tài khoản','Chứng cứ khôi phục còn hợp lệ?','Vé sai/hết hạn/đã dùng, mật khẩu không đủ điều kiện hoặc email không khớp.','Mật khẩu mới thay mật khẩu cũ; các JWT mang phiên bản cũ bị vô hiệu.','Báo cáo phân biệt luồng giao diện ba bước với nhánh API tương thích code/token trong backend.')
add(C,'Xem menu, tìm kiếm và lọc sản phẩm','CatalogSearchService.search','MarketController','templates/customer/marketplace.html; static/js/customer/marketplace.js','Product; Category; Shop','Tra cứu menu có phân trang và các tiêu chí sắp xếp được triển khai.','Từ khóa, category/shop tùy chọn, min/max, sort, page, size.','Endpoint công khai; chỉ sản phẩm/danh mục và cơ sở đang hoạt động được đưa vào tập kết quả.','Kiểm tra bộ lọc và phân trang | Chuẩn hóa tiếng Việt khi tìm tên món/danh mục | Lọc theo cơ sở và danh mục nếu có | Gom theo menuVariantIdentity để tránh lặp giữa cơ sở | Lọc giá, sắp xếp và trả trang dữ liệu','Bộ lọc và khoảng trang hợp lệ?','Giá âm, min lớn hơn max, page/size vượt giới hạn hoặc truy vấn quá dài.','Danh sách phản ánh dữ liệu hiện có; không tự gán cơ sở phục vụ của đơn.','Sort có newest, giá, đánh giá, yêu thích và bán chạy theo các truy vấn trong service.')
add(C,'Xem chi tiết, chọn size và topping','CatalogSearchService.options','MarketController','templates/fragments/product-options.html; static/js/customer/menu-selection.js','Product; Category','Cung cấp hộp chọn món trên menu, không tạo một trang chi tiết không tồn tại.','ID món được chọn, size, số lượng, ghi chú, topping khi cho phép.','Món tồn tại và còn một biến thể đang bán trong menu.','Tìm món nguồn | Gom các biến thể menu đang hoạt động | Lấy các size cùng tên và danh sách topping | Xác định allowTopping từ danh mục | Trả MenuOptions cho modal','Biến thể còn được phục vụ?','Món không tồn tại hoặc tất cả biến thể đã ngừng bán.','Khách lựa chọn cấu hình trước khi đưa vào giỏ; giá cuối vẫn kiểm tra theo cơ sở ở backend.','Chi tiết sản phẩm là modal có thật, không mô tả route /product-detail tự tạo.')
add(C,'Lưu và đồng bộ giỏ hàng tài khoản','CustomerDataService.replaceCart','CustomerDataController',cart,'AccountCart; Product; Category','Lưu giỏ của khách đăng nhập và chống ghi đè thay đổi từ thiết bị khác.','Danh sách món, số lượng, ghi chú, toppingIds và If-Match version.','CurrentActor có accountId; phiên bản gửi lên khớp bản hiện tại.','Khóa AccountCart theo tài khoản | So sánh phiên bản | Chuẩn hóa món/topping sang menu chung và kiểm tra lựa chọn | Gộp lựa chọn giống nhau rồi serialize vào ItemsJson | Tăng Revision và trả giỏ mới','If-Match và lựa chọn hợp lệ?','Giỏ đã thay đổi, topping không được phép hoặc dữ liệu không hợp lệ.','Giỏ server có phiên bản mới; client tải lại khi xung đột.','Khách chưa đăng nhập dùng localStorage trong CustomerApp; không tuyên bố giỏ khách tạm đã được lưu vào DB.')
add(C,'Lấy lại giỏ đã lưu','CustomerDataService.cart','CustomerDataController',cart,'AccountCart; Product','Phục hồi giỏ tài khoản khi tải trang hoặc đăng nhập.','Tác nhân từ tài khoản hiện tại.','Đã đăng nhập và phiên bản JWT còn hợp lệ.','Xác định accountId từ actor | Đọc hoặc tạo bản giỏ | Tính lại dữ liệu hiển thị từ sản phẩm | Trả items và version','Có tài khoản xác thực?','Khách ẩn danh bị chặn đối với endpoint giỏ tài khoản.','Client khôi phục giỏ cùng phiên bản; giỏ tạm có thể được gộp theo mã JavaScript hiện có.','Không lấy accountId tùy ý do frontend gửi làm quyền truy cập.')
add(C,'Nhận diện bàn bằng QR hợp lệ','TableContextService.readByQr','TableController','static/js/customer/customer.js; templates/customer/cart.html','DiningTable; TableSession; TableSessionAccess','Lấy ngữ cảnh bàn/cơ sở từ mã QR thực tế, tái dùng cơ chế phiên bàn.','Mã qrCode từ đường dẫn hoặc ngữ cảnh đã quét trong tab.','Bàn tồn tại, active=true; cơ sở phục vụ được xác định hợp lệ.','Tìm bàn theo mã QR | Kiểm tra bàn hoạt động và xác định cơ sở | Nếu có phiên OPEN thì lấy phiên | Cấp token phiên scoped nếu phiên còn mở | Trả tên bàn và ngữ cảnh cho checkout','QR và bàn còn hợp lệ?','QR rỗng/sai, bàn ngừng hoạt động hoặc cơ sở không được cấu hình.','Xem QR chưa tự mở phiên; số bàn không thay thế mã QR bí mật.','Checkout không hiện ô tự chọn hình thức/cơ sở; ngữ cảnh bàn hợp lệ tự quyết định nhánh DINE_IN.')
add(C,'Kiểm tra tổng tiền trước gửi đơn','OrderService.quote','OrderController','static/js/customer/delivery-checkout.js; templates/fragments/delivery-checkout.html','Product; Shop; GlobalSettings','Hiển thị giá trị phải thanh toán từ dữ liệu server trước khi xác nhận tạo đơn.','Các dòng giỏ và shopId chỉ khi có ngữ cảnh bàn; không lấy giá do client cung cấp.','Cơ sở phục vụ đúng ngữ cảnh hoặc mặc định POS; món còn hoạt động.','Xác định cơ sở và quyền mua | Ánh xạ món/topping về giá của cơ sở | Nhân số lượng để cộng tạm tính | Áp dụng cấu hình giảm giá và trả shippingFee=0 | Trả shopId, subtotal, discountAmount, totalAmount','Menu cơ sở có phục vụ giỏ?','Món không tồn tại/ngừng bán, cơ sở chưa sẵn sàng hoặc cấu hình không hợp lệ.','Không tạo Order hay Payment ở bước quote.','Ô mã giảm giá đã bỏ khỏi giao diện khách; backend còn nhánh voucher cho tính tương thích và API quản trị.')
add(C,'Gửi đơn mang về qua bước chọn thanh toán','OrderService.createCounterOrder','OrderController',cart+'; static/js/customer/delivery-checkout.js','Order; OrderItem; OrderItemTopping; Invoice; Shop','Tạo đơn mang về sau khi khách bấm Gửi đơn hàng, chọn phương thức và xác nhận trong dialog.','Danh sách món/topping, paymentMethod, expectedTotal, Idempotency-Key.','Giỏ không rỗng; quote hợp lệ; cơ sở POS đã được xác định; công thức món hợp lệ.','Khóa cơ sở và kiểm tra quyền mua | Kiểm tra khóa idempotency và fingerprint | Lưu Order nguồn COUNTER, phương thức yêu cầu và snapshot món | Tính tổng/giảm giá lại và tạo Invoice | Cấp token chứng từ riêng, audit và sự kiện sau commit','Yêu cầu mới và tổng tiền còn khớp?','Replay khác chủ/nội dung, giá đổi, món thiếu công thức, cơ sở ngừng phục vụ.','Đơn CUSTOMER ở CHO_XAC_NHAN, chưa có Payment. Chỉ xóa giỏ khi API tạo đơn thành công.','Đóng hộp thanh toán chưa tạo đơn; lựa chọn tiền mặt/chuyển khoản không tự làm PAID.')
add(C,'Gửi đơn tại bàn theo phiên được xác thực','OrderService.createTableOrder','OrderController',cart,'DiningTable; TableSession; Order; Invoice','Gắn đơn mới vào đúng bàn, đúng phiên và cơ sở phục vụ.','tableId, expectedSessionId, qrCode hoặc tableToken, items và phương thức.','Có QR đúng bàn hoặc token phiên còn hạn; nhân viên POS có quyền tương ứng.','Khóa bàn và kiểm tra bằng chứng truy cập | Ràng buộc shopId với cơ sở bàn | Phát hiện replay; đối chiếu phiên dự kiến | Mở phiên khi chưa có hoặc lấy phiên OPEN đúng bàn | Tạo đơn, invoice, chứng từ riêng và phát sự kiện','Bằng chứng và phiên bàn khớp?','Giả mạo QR/token, đổi cơ sở, phiên cũ/đóng hoặc món không thể phục vụ.','Đơn TABLE tham chiếu phiên xác thực; người khác không được truy cập lịch sử từ ID bàn.','Giỏ riêng của khách không xóa giỏ phiên POS dùng chung. Không cho khách tự gán bàn bằng ID có thể đoán.')
add(C,'Thông báo chuyển khoản để thu ngân đối soát','PaymentService.createNoticeForOrder','PaymentController','templates/customer/order-confirmation.html; static/js/customer/order-confirmation.js','Order; Invoice; PaymentNotice','Ghi nhận khách đã chuyển khoản để thu ngân kiểm tra giao dịch thực tế.','Mã đơn, method=BANK_TRANSFER, reference và khóa yêu cầu.','Controller xác minh chủ đơn hoặc chứng từ riêng; hóa đơn chưa thu, đơn chưa hủy.','Kiểm tra quyền đọc đơn ở controller | Tìm invoice và khóa đơn rồi hóa đơn | Từ chối đơn hủy/đã thu và phát hiện notice trùng | Lưu PaymentNotice theo phương thức | Ghi audit và thông báo thu ngân','Hóa đơn còn cần thanh toán?','Không có quyền, hóa đơn hủy, đã được ghi thu hoặc dữ liệu phương thức sai.','Đơn giữ trạng thái chưa thanh toán; chưa tạo Payment và không tự xác nhận tiền ngân hàng.','Tài khoản nhận tiền lấy từ GlobalSettings; URL VietQR chỉ có khi cấu hình BIN/tài khoản phù hợp. Chưa có xác nhận giao dịch ngân hàng tự động cho luồng POS này.')
add(C,'Theo dõi chứng từ đơn vừa đặt','OrderService.getOrderForCustomer','OrderController','templates/customer/order-confirmation.html; static/js/customer/order-confirmation.js','Order; Invoice; CounterOrderAccess; Payment','Cho phép xem một đơn được sở hữu hoặc được cấp capability riêng.','orderId và JWT tài khoản hoặc token riêng của đúng đơn.','Có quyền với chính đơn cần xem.','Tìm Order theo ID | Xác minh ADMIN/CASHIER theo cơ sở hoặc chủ tài khoản | Với guest kiểm tra orderId trong capability | Ánh xạ sản phẩm, hóa đơn và tình trạng thu tiền | Trả chi tiết cho trang xác nhận và polling','Actor có quyền với đúng đơn?','Không tìm thấy đơn hoặc token/tài khoản không có quyền.','Trả dữ liệu một chứng từ; token bàn không cấp quyền xem mọi đơn trong phiên.','Tiền mặt hiện yêu cầu trả tại quầy; chuyển khoản hiện thông tin cấu hình hoặc thông báo chưa có tài khoản ngân hàng.')
add(C,'Xem lịch sử đơn hàng tài khoản','OrderService.getOrdersForCustomer','OrderController',orders,'Order; Account; Invoice; Payment','Tra cứu những đơn thuộc tài khoản đăng nhập.','JWT tài khoản; không nhận accountId từ trình duyệt làm phạm vi.','Customer history controller yêu cầu tài khoản xác thực.','Xác định actor | Với khách lấy đơn theo accountId | Với nhân viên lọc quyền cơ sở theo service | Sắp xếp theo thời gian tạo giảm dần | Ánh xạ hóa đơn và tình trạng thanh toán','Tài khoản đã xác thực?','Guest không được liệt kê lịch sử chỉ bằng QR/token phiên bàn.','Danh sách mới nhất trước, dữ liệu chỉ thuộc phạm vi cho phép.','Lịch sử giao hàng cũ được lưu riêng; không gộp DeliveryOrder thành Order một cách giả định.')
add(C,'Yêu cầu hủy đơn trước chế biến','CancellationService.requestCancellation','CancellationController',orders,'Order; CancellationRequest; Invoice; BusinessAudit','Hủy trực tiếp hoặc xin duyệt theo trạng thái chế biến và việc thu tiền.','orderId và lý do hủy.','Là chủ đơn/actor có quyền; đơn chưa DANG_CHE_BIEN hoặc HOAN_THANH.','Khóa đơn và xác minh quyền | Kiểm tra trạng thái được hủy | Nếu chưa thu hoặc còn chờ xác nhận thì hủy trực tiếp hóa đơn/đơn | Nếu đã thu và chờ chế biến thì lập yêu cầu CHO | Ghi audit và phát cập nhật','Có thể hủy trực tiếp theo tiền/trạng thái?','Đơn đã pha/hoàn tất, actor khác hoặc đã có yêu cầu CHO.','Hủy không đồng nghĩa tự hoàn tiền; refund là nghiệp vụ riêng có chứng từ.','Không ghi trả nguyên liệu đã tiêu hao bằng một thao tác hủy đơn; không mô tả chức năng trả hàng POS sau khi uống nếu source không có.')
add(C,'Xem và sửa thông tin cá nhân','AuthService.updateProfile','AuthController','templates/profile.html','Account','Cập nhật thông tin liên hệ thuộc tài khoản đang đăng nhập.','Họ tên, số điện thoại qua UpdateProfileRequest.','Actor có accountId hợp lệ.','Tìm Account hiện tại | Chỉ cập nhật trường được DTO cho phép | Chuẩn hóa nội dung nhập | Lưu Account | Trả UserInfo hiện tại','Tài khoản có tồn tại?','Không tìm thấy tài khoản hoặc dữ liệu không thỏa validation phía giao diện/API.','Không thay đổi vai trò hay quyền quản trị qua chức năng sửa hồ sơ.','Ảnh đại diện có endpoint upload riêng, không phải trường tùy ý sửa avatar nội bộ.')
add(C,'Đổi mật khẩu khi đang đăng nhập','AuthService.changePassword','AuthController','templates/profile.html','Account','Cho phép người dùng chủ động đổi mật khẩu bằng mật khẩu hiện tại.','currentPassword và newPassword.','Đang đăng nhập; mật khẩu hiện tại phải khớp hash trong DB.','Tìm tài khoản hiện tại | So khớp mật khẩu cũ | BCrypt mật khẩu mới | Tăng tokenVersion | Lưu tài khoản','Mật khẩu hiện tại đúng?','Mật khẩu cũ sai, tài khoản không tồn tại hoặc DTO mật khẩu mới không hợp lệ.','Thông tin đăng nhập cũ bị thay thế và JWT phiên bản cũ không còn hiệu lực.','Đây là luồng khác với khôi phục mật khẩu bằng OTP; không yêu cầu email OTP trong method này.')
add(C,'Đánh dấu yêu thích và ghi nhận món đã xem','CustomerDataService.interest','CustomerDataController','templates/customer/account-data.html; static/js/customer/account-data.js; static/js/customer/marketplace.js','ProductInterest; Product; Account','Lưu lựa chọn và lịch sử xem phục vụ trải nghiệm tài khoản.','productId; enabled khi yêu thích hoặc cờ viewed qua endpoint riêng.','Có accountId và sản phẩm hợp lệ.','Xác định chủ tài khoản | Tìm món và bản ghi quan tâm | Cập nhật trạng thái yêu thích hoặc thời điểm đã xem | Lưu ProductInterest | Trả danh sách qua interests khi cần','Sản phẩm còn tồn tại?','Không có tài khoản hoặc mã món không hợp lệ.','Dữ liệu quan tâm thuộc từng tài khoản, không phát sinh đơn hàng.','Phân hệ preferences có đường dẫn thực /api/v1/account/preferences; lịch sử quan tâm không thay thế lịch sử mua hàng.')
add(C,'Đánh giá món đã mua và hoàn tất','ReviewService.create','ReviewController','templates/customer/orders.html; static/js/order/orders.js; static/js/customer/marketplace.js','ProductReview; Order; Payment; DeliveryOrder','Ghi nhận đánh giá có điều kiện mua hàng và ngăn đánh giá lặp.','productId, orderId, stars, comment, delivery.','Tài khoản có đơn chứa món; POS phải HOAN_THANH và đã thu đủ; comment ít nhất 50 ký tự.','Khóa Account và kiểm tra chưa đánh giá món | Tìm sản phẩm | Phân biệt đơn POS và lịch sử giao hàng | Xác minh chủ đơn, món, trạng thái và thu tiền | Lưu ProductReview và trả dữ liệu','Có chứng từ mua hợp lệ và chưa đánh giá?','Chưa mua/chưa trả tiền, bình luận ngắn, đơn không khớp hoặc đánh giá trùng.','Đánh giá được gắn với bằng chứng đơn tương ứng.','Chưa có API kiểm duyệt/phản hồi đánh giá trong ReviewController hiện tại; không đưa chức năng đó thành đã triển khai.')
add(C,'Đính kèm ảnh hoặc video cho đánh giá','ReviewService.media','ReviewController','static/js/customer/marketplace.js','ProductReview; ReviewMedia','Lưu minh họa đánh giá qua dịch vụ ảnh đã tích hợp.','reviewId và MultipartFile JPEG/PNG/WebP/MP4 trong giới hạn 20MB.','Là chủ đánh giá; Cloudinary được cấu hình hợp lệ.','Tìm đánh giá và xác minh chủ sở hữu | Kiểm tra dung lượng, MIME và nội dung tệp | Upload Cloudinary theo loại media | Lưu ReviewMedia | Đăng ký dọn media nếu transaction không commit','Tệp đúng định dạng và chủ đánh giá?','Tệp sai nội dung/kích thước, không có quyền hoặc dịch vụ ảnh lỗi.','Chỉ URL/publicId cần quản lý được lưu vào chứng từ media; không lưu file lớn trong bảng.','Đã xác minh source validation và cleanup; phiên báo cáo không upload ảnh/video thật lên tài khoản bên ngoài.')
add(C,'Quản lý địa chỉ đã lưu cho dữ liệu tương thích','CustomerDataService.saveAddress','CustomerDataController','templates/customer/account-data.html; static/js/customer/account-data.js','DeliveryAddress; Account','Bảo toàn hồ sơ địa chỉ đang tồn tại trong module tài khoản cũ.','Người nhận, điện thoại, địa chỉ, mặc định và tọa độ tùy chọn.','Địa chỉ thuộc tài khoản; tối đa 20 bản ghi.','Xác định accountId | Tạo mới hoặc lấy đúng địa chỉ chủ sở hữu | Kiểm tra giới hạn và thông tin | Cập nhật thuộc tính/mặc định | Lưu và trả AddressView','Địa chỉ thuộc chủ tài khoản và còn giới hạn?','Không tồn tại, không có quyền hoặc vượt 20 địa chỉ.','Địa chỉ được lưu nhưng không là điều kiện bắt buộc của checkout mang về/tại quán.','Module dữ liệu còn tồn tại; không được mô tả như UTE-Tea đang cung cấp giao tận nơi.',status='Mã nguồn tương thích; tách khỏi checkout mới')
add(T,'Xem hàng đợi và bộ lọc đơn','OrderService.getOrdersForCashier','OrderController',cash,'Order; Invoice; PaymentNotice; Payment','Tập trung các đơn cần xác nhận, chế biến, thu tiền, hủy và hoàn tiền.','status, paymentStatus, tab, query.','Vai trò CASHIER/ADMIN; nhân viên thuộc đúng cơ sở với đơn mới.','Lấy tập đơn phù hợp | Lọc staffCanRead theo phân công cơ sở | Ánh xạ hóa đơn, notice và refund | Lọc theo tab/trạng thái/từ khóa | Sắp xếp đơn mới nhất trước','Nhân viên có phạm vi cơ sở?','Bị Security từ chối hoặc không có bản ghi trong phạm vi; danh sách rỗng là kết quả hợp lệ.','Không cấp quyền chi nhánh khác chỉ do nhập ID/mã đơn.','Hàng đợi hiển thị trạng thái nghiệp vụ và thu tiền riêng; chưa PAID vẫn có thể được điều phối pha chế.')
add(T,'Tiếp nhận và xác nhận đơn khách','OrderService.confirm','OrderController',cash,'Order; Invoice; BusinessAudit','Chuyển đơn khách đang chờ xác nhận sang hàng đợi bếp.','orderId, actor thu ngân.','Đúng cơ sở và trạng thái CHO_XAC_NHAN.','Khóa Order | Kiểm tra phạm vi thu ngân và trạng thái | Tìm hóa đơn | Chuyển CHO_CHE_BIEN | Ghi audit và gửi sự kiện cashier/kitchen sau commit','Đơn đang chờ xác nhận?','Đơn không đúng trạng thái hoặc không thuộc cơ sở.','Bếp nhìn thấy đơn trong hàng đợi chế biến.','Không áp đặt paid gate mới: quy trình cho phép tiền mặt/chuyển khoản trước, trong hoặc sau pha chế.')
add(T,'Tạo đơn tại quầy bằng POS','OrderService.createCounterOrder','OrderController',cash,'Order; OrderItem; Invoice; CounterOrderAccess','Cho thu ngân lập đơn trực tiếp từ menu và nhận tiền theo thao tác POS.','items, note, shopId mặc định, paymentMethod, Idempotency-Key.','Nhân viên đúng quyền cơ sở; món và công thức còn hợp lệ.','Khóa cơ sở phục vụ | Đối chiếu key chống lặp | Tạo Order nguồn COUNTER với actor nhân viên | Snapshot món/topping và tạo Invoice | Gửi chứng từ mới về POS','Dữ liệu POS và key còn hợp lệ?','Món ngừng bán, cơ sở khác hoặc key đã dùng cho nội dung khác.','Đơn do nhân viên tạo ở CHO_THANH_TOAN; JavaScript ghi thu bằng API riêng.','Không coi việc tạo đơn POS là bằng chứng đã thu tiền; cần PaymentService.recordReceipt thật sự hoàn tất.')
add(T,'Ghi thu tiền mặt hoặc chuyển khoản','PaymentService.recordReceipt','PaymentController',cash,'Order; Invoice; Payment; BusinessAudit','Tạo khoản thu duy nhất sau khi thu ngân thực tế nhận tiền.','invoiceId, method, reference, Idempotency-Key và cashierId từ actor.','Hóa đơn hiệu lực, đơn chưa hủy, nhân viên đúng cơ sở.','Khóa bàn nếu có rồi khóa đơn và hóa đơn | Kiểm tra quyền và replay cùng invoice/phương thức | Từ chối hóa đơn hủy hoặc đã ghi thu | Tạo Payment bằng totalAmount server | Cập nhật trạng thái cần thiết và audit/sự kiện','Được phép ghi thu và chưa có khoản thu?','Sai quyền, key khác invoice/phương thức, số tiền không hợp lệ hoặc đã thanh toán.','Thanh toán được chứng minh bằng Payment; không tạo khoản thu thứ hai cho hóa đơn.','Thu ngân phải đối soát chuyển khoản thủ công; code không liên hệ ngân hàng để chứng minh số dư.')
add(T,'Xác nhận thông báo chuyển khoản của khách','PaymentService.confirmTransferReceiptForOrder','PaymentController',cash,'Order; Invoice; Payment; PaymentNotice','Đối soát thông báo của khách trước khi ghi thu BANK_TRANSFER.','orderId; Idempotency-Key tùy chọn.','Thu ngân được phân công và đã kiểm tra giao dịch ngoài hệ thống.','Tìm invoice theo Order | Kiểm tra phạm vi cơ sở | Trả khoản thu nếu trước đó đã xử lý | Tạo yêu cầu BANK_TRANSFER với reference xác nhận | Gọi chung recordReceipt','Đã có khoản thu hợp lệ chưa?','Sai cơ sở, đơn không có hóa đơn hoặc trạng thái không cho ghi thu.','Tái sử dụng kiểm tra và khóa ghi thu thay vì tạo cổng thanh toán giả.','Hành động xác nhận là trách nhiệm thu ngân; không kích hoạt từ nút Tôi đã chuyển khoản của khách.')
add(T,'Mở phiên phục vụ bàn','TableSessionService.openByCashier','TableController',cash,'DiningTable; TableSession; SessionCart; BusinessAudit','Chủ động mở lượt phục vụ trước khi khách hoặc thu ngân đặt món.','tableId và cashierId.','Bàn hoạt động; nếu đã ánh xạ cơ sở thì staff có quyền tương ứng.','Khóa DiningTable | Trả phiên OPEN đang có nếu phù hợp | Tạo TableSession OPEN | Đặt bàn CO_KHACH và activeSessionId | Tạo SessionCart, audit và sự kiện','Bàn đã có phiên OPEN?','Không tìm thấy bàn hoặc nhân viên không có quyền cơ sở.','Một activeSessionId được gắn trên bàn và giỏ phiên được khởi tạo.','Không tự mở thêm phiên chỉ vì khách xem QR; thao tác mở phiên này thuộc thu ngân.')
add(T,'Gắn đơn quầy vào bàn cùng cơ sở','OrderService.assignCounterOrderToTable','OrderController',cash,'Order; DiningTable; TableSession','Chuyển vị trí phục vụ của cùng đơn quầy, không tạo đơn hoặc thu lại tiền.','orderId và tableId.','Đơn nguồn COUNTER chưa có session; thu ngân đúng cơ sở; bàn cùng cơ sở.','Khóa đơn và kiểm tra nguồn | Từ chối đơn đã gắn phiên | Khóa bàn và đối chiếu cơ sở | Mở/lấy phiên bằng TableSessionService | Gắn session vào chính Order và ghi audit','Đơn quầy chưa gắn và cùng cơ sở?','Đã có session, nguồn không phải COUNTER hoặc bàn ở cơ sở khác.','Mã đơn/hóa đơn giữ nguyên; vị trí phục vụ có session.','Không thể dùng frontend tableId để chuyển một đơn sang chi nhánh khác.')
add(T,'Đóng phiên bàn sau phục vụ','TableSessionService.closeBySessionId','TableController',cash,'DiningTable; TableSession; TableSessionAccess; SessionCart','Kết thúc lượt dùng bàn khi các đơn/chứng từ đã đủ điều kiện.','sessionId và nhân viên thu ngân.','Phiên hiện tại của bàn; đơn đã xong/hủy và hóa đơn hiệu lực đã được thu đủ theo closeSession.','Tìm phiên và đối chiếu bàn | Khóa bàn và phiên hiện hành | Kiểm tra đơn và hóa đơn của lượt phục vụ | Đóng phiên, xóa activeSessionId và quyền tạm | Phát sự kiện TABLE_SESSION_CLOSED','Mọi đơn và hóa đơn đủ điều kiện đóng?','Phiên cũ, còn đơn xử lý hoặc hóa đơn chưa thu đủ.','Bàn sẵn sàng cho lượt mới; chứng từ lịch sử không bị xóa.','Thanh toán, logout hoặc mất WebSocket không tự đóng phiên; thao tác phải từ thu ngân.')
add(T,'Duyệt hoặc từ chối yêu cầu hủy','CancellationService.decideCancellation','CancellationController',cash,'CancellationRequest; Order; Invoice; BusinessAudit','Giải quyết yêu cầu CHO của khách khi đơn đã thu tiền nhưng chưa pha.','requestId, approved và lý do quyết định.','Vai trò được endpoint cho phép; yêu cầu còn CHO và đơn chưa bắt đầu pha.','Khóa yêu cầu và Order | Kiểm tra đã xử lý và trạng thái bếp | Nếu duyệt thì hủy Order và Invoice | Lưu quyết định, người xử lý và thời gian | Audit và thông báo client','Yêu cầu còn chờ và đơn chưa pha?','Đã quyết định hoặc đơn chuyển sang DANG_CHE_BIEN/HOAN_THANH.','Yêu cầu kết thúc có chứng từ quyết định; hoàn tiền được xử lý riêng.','Cần phân biệt quyền role endpoint với kiểm tra cơ sở: các method hủy/hoàn chưa đồng nhất assertStaff như OrderService; báo cáo không khẳng định đã bao phủ tất cả.')
add(T,'Hoàn tiền mặt và lập yêu cầu hoàn chuyển khoản','RefundService.refundCash','CancellationController',cash,'RefundRequest; Order; Invoice; Payment','Theo dõi việc trả lại khoản đã thu cho một đơn bị hủy.','orderId, cashierId; nhánh ngân hàng dùng requestBankRefund.','Order đã DA_HUY và có Payment; chưa hoàn trước đó.','Khóa đơn và kiểm tra trạng thái hủy | Lấy invoice và Payment đã ghi thu | Kiểm tra yêu cầu hoàn hiện có | Lưu chứng từ hoàn tiền mặt và người thực hiện | Ghi audit và sự kiện','Đơn đã thu và chưa hoàn tiền?','Đơn chưa hủy, chưa thu hoặc đã hoàn.','Tiền mặt ghi nhận hoàn trực tiếp; chuyển khoản có quy trình xin duyệt quản trị riêng.','Không xóa Payment gốc để giả lập hoàn tiền. Chứng từ hoàn giữ liên kết với đơn bị hủy.')
add(K,'Xem hàng đợi bếp theo cơ sở','OrderService.getOrdersForKitchen','OrderController',kitchen,'Order; Invoice; OrderItem','Cung cấp những đơn được thu ngân điều phối và đang thực hiện.','Actor KITCHEN/ADMIN, trạng thái hàng đợi server.','JWT vai trò bếp; có phân công cơ sở khi đơn mới mang ShopId.','Truy vấn CHO_CHE_BIEN và DANG_CHE_BIEN | Lọc staffCanRead | Ánh xạ món, topping và thông tin bàn | Sắp theo thời điểm tạo | Trả danh sách cho giao diện bếp','Có đơn thuộc phạm vi chế biến?','Không có quyền; hàng đợi rỗng là trạng thái hợp lệ.','Không đưa đơn CHO_XAC_NHAN chưa điều phối vào hàng đợi chế biến.','Payment không phải điều kiện bắt buộc để bếp thấy đơn đã được xác nhận.')
add(K,'Bắt đầu chế biến đơn','OrderService.start','OrderController',kitchen,'Order; CancellationRequest; BusinessAudit','Xác nhận bếp đã bắt đầu xử lý toàn đơn.','orderId và kitchenId.','Đơn CHO_CHE_BIEN, đúng cơ sở, không có yêu cầu hủy CHO.','Khóa Order và kiểm tra nhân viên | Kiểm tra trạng thái được bắt đầu | Kiểm tra yêu cầu hủy đang chờ | Chuyển DANG_CHE_BIEN và startedAt | Ghi audit và thông báo','Không có yêu cầu hủy đang chờ?','Đơn sai trạng thái, khác cơ sở hoặc CANCELLATION_PENDING.','Hủy trước pha không còn được xử lý như đơn chưa bắt đầu.','Hệ thống cập nhật trạng thái toàn đơn, không dựng trạng thái chế biến cho từng món.')
add(K,'Hoàn thành đơn và tiêu hao nguyên liệu','OrderService.complete','OrderController',kitchen,'Order; OrderIngredientSnapshot; Stock; StockMovement','Hoàn tất chế biến cùng việc ghi trừ nguyên liệu theo snapshot.','orderId và nhân viên bếp.','Đúng trạng thái được complete, đúng cơ sở và tồn kho đủ theo snapshot.','Khóa Order và kiểm tra trạng thái | Gọi completeOrderConsumption trong transaction | Khóa các dòng tồn kho và trừ lượng cần | Chuyển HOAN_THANH, đặt completedAt | Audit và sự kiện sau commit','Tồn kho đủ và trạng thái cho hoàn tất?','Thiếu tồn kho, snapshot không hợp lệ hoặc trạng thái không phù hợp.','Đơn hoàn thành và biến động kho cùng được commit; không tự đóng bàn.','Nếu transaction thất bại không được báo hoàn thành thành công chỉ vì UI đổi nút.')
add(K,'Theo dõi tồn kho và cảnh báo ngưỡng','InventoryService.getStocksWithFilter','InventoryController',inv,'Stock; Material','Tra cứu lượng tồn ở KHO/BEP và các mức cảnh báo.','location, type, alertFilter, query.','Vai trò được nhóm API inventory cho phép; bộ lọc theo dữ liệu hiện có.','Chọn tập tồn theo vị trí và loại nguyên liệu | Chuẩn hóa từ khóa | Tính trạng thái cảnh báo theo ngưỡng | Ghép thông tin tên/đơn vị/giá trị tồn | Trả StockSummaryResponse','Dòng tồn có khớp bộ lọc?','Không có quyền hoặc tập kết quả rỗng.','Chỉ đọc tồn; không làm thay đổi số lượng khi đổi tab/lọc.','Giao diện tồn được dùng chung cho nhóm quyền phù hợp; không khẳng định mọi báo cáo kho đã tách ShopId vì schema Stock khóa theo material/location.')
add(K,'Ghi mẻ sơ chế từ định mức','InventoryService.recordPreparation','InventoryController',inv,'PreparationBatch; PreparationBatchItem; PreparationRecipe; Stock','Chuyển nguyên liệu đầu vào thành bán thành phẩm với lượng thực tế, giá vốn và dấu vết mẻ.','Nguyên liệu đầu ra, sản lượng thực tế, định mức, số lượng đầu vào và Idempotency-Key.','Định mức sơ chế hoạt động; loại đầu ra phù hợp; tồn đầu vào đủ; người dùng đúng quyền.','Kiểm tra chống lặp và cấu hình định mức | Chuẩn hóa nguyên liệu đầu vào theo công thức | Khóa tồn và kiểm tra lượng có thể sử dụng | Trừ đầu vào, cộng thành phẩm và tính giá vốn | Lưu mẻ, chi tiết, movements và audit','Định mức và tồn đầu vào hợp lệ?','Thiếu tồn, sản lượng không hợp lệ, công thức thiếu hoặc yêu cầu trùng khác nội dung.','Có chứng từ mẻ và nhật ký các biến động liên quan trong một giao dịch.','Không bịa định lượng khi source/cấu hình chưa có; một số overload là wrapper, báo cáo trích overload xử lý chính.')
add(K,'Nhập nguyên liệu thô vào kho tổng','InventoryService.recordImport','InventoryController',inv,'ImportReceipt; ImportReceiptItem; Stock; StockMovement','Ghi phiếu nhập và cập nhật đơn giá bình quân theo dữ liệu nhập.','Danh sách nguyên liệu, lượng nhập, giá nhập; idempotencyKey và người ghi.','Chỉ THO được nhập tại KHO; số lượng và đơn giá hợp lệ.','Kiểm tra key chống lặp | Tìm nguyên liệu và kiểm tra loại THO | Khóa tồn và tính giá vốn bình quân | Cộng số lượng vào KHO | Lưu phiếu nhập, chi tiết và biến động','Loại nguyên liệu, số lượng và giá hợp lệ?','Nguyên liệu không tồn tại, đơn giá âm, dữ liệu vốn cũ thiếu hoặc nội dung trùng xung đột.','Tồn và giá vốn phản ánh phiếu nhập; giữ chứng từ thay vì sửa số lượng ngầm.','Controller có kiểm tra quyền ghi nhập; không suy ra bất kỳ actor có quyền xem inventory đều được thực hiện mọi lệnh.')
add(K,'Ghi hao hụt và nguyên liệu loại bỏ','InventoryService.recordWaste','InventoryController',inv,'Material; Stock; StockMovement; BusinessAudit','Ghi nhận nguyên liệu thất thoát/hủy bằng lượng và lý do thực tế.','materialId, vị trí, lượng hao hụt, lý do.','Có tồn tại vị trí; KHO chỉ áp dụng THO; số lượng không vượt tồn.','Tìm nguyên liệu và kiểm tra vị trí/loại | Khóa Stock | Đối chiếu số lượng muốn loại bỏ | Trừ tồn và ghi movement hao hụt | Audit với người thực hiện','Tồn đủ để ghi hao hụt?','Không có nguyên liệu/tồn, loại không phù hợp hoặc lượng vượt tồn.','Tồn giảm và có chứng từ giải thích hao hụt.','Không tự bù kho bằng việc sửa một đơn hàng đã hoàn tất.')
add(K,'Ghi nhận và xử lý sự cố chế biến','InventoryService.recordIncident','KitchenOrderController',kitchen,'BusinessAudit; Order','Ghi chú sự cố theo mã đơn để giữ lịch sử xử lý của bếp.','orderId, nội dung IncidentRequest, actor hiện tại.','Đơn tồn tại; actor được API bếp cho phép.','Tìm Order | Tạo thông tin sự cố theo request | Ghi BusinessAudit liên quan đơn | Trả IncidentResponse | Khi xử lý dùng resolveIncident để ghi dấu vết tiếp theo','Đơn cần ghi sự cố có tồn tại?','Không tìm thấy đơn hoặc dữ liệu request không hợp lệ.','Sự cố được xem lại qua getIncidents; không phát sinh một entity Incident không có trong source.','Báo cáo nêu đúng lưu trữ bằng audit; không tự đặt bảng SuCoPhaChe.')
add(K,'Ghi tiêu hao bổ sung khi pha bù','InventoryService.recordAdditionalConsumption','KitchenOrderController',kitchen,'Order; Stock; Material; StockMovement','Tách lượng pha bù khỏi tiêu hao snapshot ban đầu của đơn.','orderId, các dòng nguyên liệu và lượng dùng thêm.','Có đơn, có nguyên liệu và tồn BEP đủ.','Tìm Order và dữ liệu bổ sung | Tìm nguyên liệu tương ứng | Khóa tồn BEP | Trừ lượng bổ sung và ghi biến động | Lưu audit theo đơn/người thực hiện','Tồn BEP đủ cho lượng pha bù?','Nguyên liệu/tồn không tồn tại hoặc thiếu lượng để pha bù.','Tồn kho có dấu vết riêng cho lượng phát sinh thực tế.','Không thay thế hoặc sửa ngược snapshot món ban đầu để che lượng dùng thêm.')
add(K,'Kiểm kê và kết ca kho','InventoryService.recordShiftSettlement','InventoryController',inv,'ShiftSettlement; ShiftSettlementItem; Stock; StockMovement','Chốt tồn thực tế và hao hụt cuối ca bằng chứng từ đối chiếu sổ sách.','location, dòng kiểm kê, số lượng thực tế và lý do.','ADMIN/KITCHEN theo PreAuthorize; dữ liệu có dòng và tồn thực tế thỏa điều kiện.','Lấy preview tồn sổ sách | Kiểm tra key và dữ liệu từng nguyên liệu | Khóa tồn và đối chiếu thực tế | Tính chênh lệch, cập nhật tồn/movements | Lưu biên bản kết ca và chi tiết','Số thực tế hợp lệ với sổ sách?','Danh sách rỗng, tồn không có, số lượng vượt giới hạn quy định hoặc key trùng.','Biên bản ghi sổ sách, thực tế, chênh lệch và người kết ca.','Các API list/get có dữ liệu lịch sử; không chỉ là một phép setStock không có chứng từ.')
add(K,'Xem lịch sử nhập, sơ chế và biến động','InventoryService.listMovements','InventoryController','templates/admin/documents.html; static/js/admin/documents.js','StockMovement; ImportReceipt; PreparationBatch; ShiftSettlement','Tra cứu nguyên nhân thay đổi tồn và các chứng từ vận hành.','materialId, location; các danh sách chứng từ có from/to/all theo controller.','Có quyền đọc module kho/chứng từ.','Đọc movements theo bộ lọc | Ghép dữ liệu nguyên liệu và vị trí | Sắp xếp lịch sử | Tải chứng từ nhập/sơ chế/kết ca tương ứng | Hiển thị bảng tra cứu','Có chứng từ khớp bộ lọc?','Quyền không phù hợp hoặc kết quả rỗng.','Không sửa số lượng tồn bằng thao tác xem lịch sử.','Giao diện dùng dữ liệu đã lưu, không suy luận mọi thay đổi từ chênh lệch giữa hai lần xem.')
add(A,'Quản lý tài khoản nhân viên','AdminService.createStaffAccount','AdminController','templates/admin/staff.html; static/js/admin/admin.js','Account','Tạo tài khoản nhân viên theo quyền quản trị, đồng thời quản lý hồ sơ và trạng thái.','Thông tin CreateStaffRequest: email, tên, điện thoại, vai trò và mật khẩu theo DTO.','ADMIN và dữ liệu nhân viên hợp lệ; email chưa được sử dụng.','Kiểm tra email và vai trò được phép | BCrypt mật khẩu | Tạo Account theo chính sách quản trị | Lưu tài khoản | Trả StaffResponse để hiển thị danh sách','Email và vai trò được phép?','Trùng email, vai trò không hợp lệ hoặc DTO sai.','Nhân viên có hồ sơ được quản lý tập trung.','Đây là quy trình quản trị, khác đăng ký CUSTOMER công khai phải nhập OTP. Không trích mật khẩu mẫu trong báo cáo.')
add(A,'Sửa, khóa và xóa tài khoản có kiểm soát','AdminService.toggleStaffStatus','AdminController','templates/admin/staff.html; static/js/admin/admin.js','Account; Order; BusinessAudit','Hạn chế truy cập của tài khoản và bảo vệ tài khoản quản trị đang thao tác.','accountId, active và currentAdminId từ actor.','ADMIN; không khóa/xóa trái quy định bảo vệ tài khoản.','Tìm Account | Kiểm tra giới hạn theo loại tài khoản và quản trị hiện tại | Cập nhật active và phiên bản token khi cần | Lưu Account | Trả hồ sơ cập nhật','Tài khoản có được phép thay trạng thái?','Không tồn tại, tự tác động vào tài khoản quản trị được bảo vệ hoặc có ràng buộc nghiệp vụ.','Filter JWT từ chối tài khoản inactive hoặc phiên bản cũ.','updateStaffAccount/deleteStaffAccount có kiểm tra riêng; không xem các thao tác này là xóa vật lý mọi dữ liệu liên quan.')
add(A,'Quản lý danh mục menu','AdminService.createCategory','AdminController','templates/admin/catalog.html; static/js/admin/admin.js','Category; Product','Tổ chức nhóm món và quy tắc cho phép topping.','Tên, active và allowTopping theo CategoryRequest.','ADMIN; tên danh mục đúng ràng buộc.','Kiểm tra dữ liệu danh mục | Tạo Category với các cờ nghiệp vụ | Lưu qua repository | Trả danh mục | Cho phép cập nhật/xóa theo các method liên quan','Tên và dữ liệu danh mục hợp lệ?','Tên trùng, thiếu dữ liệu hoặc ràng buộc khi xóa.','Menu đọc từ danh mục active; việc đổi allowTopping tác động kiểm tra giỏ/đơn.','Không thêm module thương hiệu không có trong mô hình vì source UTE-Tea không có entity Brand tương ứng.')
add(A,'Quản lý món, size và giá bán','AdminService.updateProduct','AdminController','templates/admin/catalog.html; static/js/admin/admin.js','Product; Category','Cập nhật danh mục, giá, mô tả và trạng thái bán của từng biến thể món.','productId và ProductRequest gồm danh mục, tên, size, giá, mô tả, active.','ADMIN; món và danh mục tồn tại; dữ liệu không trùng khóa menu.','Tìm Product và Category | Kiểm tra tên/size và dữ liệu giá | Cập nhật các trường nghiệp vụ | Lưu Product | Trả thông tin hiển thị menu','Món/danh mục tồn tại và giá hợp lệ?','Không tồn tại, trùng tên/size hoặc dữ liệu vi phạm DTO.','Giá mới được dùng cho đơn mới; snapshot của đơn cũ không đổi.','Giá theo cơ sở nằm ở Product.shop; không mô tả giá frontend là nguồn quyết định hóa đơn.')
add(A,'Quản lý ảnh sản phẩm trên Cloudinary','ProductImageService.uploadProductImage','AdminController','templates/admin/catalog.html; static/js/admin/admin.js','Product','Thay ảnh món và kiểm soát file bên ngoài transaction DB.','productId, MultipartFile và currentAdminId.','ADMIN; món tồn tại; Cloudinary hợp lệ; nội dung file được kiểm tra.','Kiểm tra tệp thực và cấu hình dịch vụ | Upload ảnh mới | Cập nhật URL/publicId trong Product | Đăng ký xóa ảnh mới nếu DB rollback | Sau commit dọn ảnh cũ khi không còn sử dụng','File và dịch vụ ảnh hợp lệ?','Sai loại/dung lượng, món không tồn tại hoặc lỗi upload.','Ảnh mới gắn với món khi DB commit; không bỏ mặc ảnh mồ côi theo nhánh xử lý đã triển khai.','Phiên báo cáo không truyền API key thật hay tải ảnh lên dịch vụ bên ngoài.')
add(A,'Thiết lập công thức định mức món','AdminService.updateProductRecipe','AdminController','templates/admin/catalog.html; static/js/admin/admin.js','ProductRecipe; Product; Material','Khai báo lượng nguyên liệu làm cơ sở snapshot và tiêu hao khi hoàn tất đơn.','productId và danh sách materialId/quantity.','ADMIN; món và từng nguyên liệu hợp lệ; định lượng dương.','Tìm sản phẩm | Kiểm tra danh sách nguyên liệu và định lượng | Đối chiếu loại/vị trí sử dụng theo mã | Cập nhật quan hệ ProductRecipe | Trả công thức mới','Định lượng và nguyên liệu hợp lệ?','Nguyên liệu không tồn tại, trùng/không hợp lệ hoặc số lượng không dương.','Đơn mới lấy snapshot từ công thức; đơn đã tạo giữ lượng snapshot của thời điểm đặt.','Không tự điền công thức giả cho món chưa được cấu hình chỉ để chứng minh checkout thành công.')
add(A,'Quản lý bàn và mã QR','AdminService.createTable','AdminController','templates/admin/tables.html; static/js/admin/table-tools.js','DiningTable','Tạo/điều chỉnh bàn phục vụ và mã QR khó đoán.','Tên bàn và trạng thái hoạt động theo TableRequest.','ADMIN; tên bàn không trùng ràng buộc.','Kiểm tra tên bàn | Sinh qrCode bằng UUID trong server | Tạo DiningTable và trạng thái ban đầu | Lưu qua repository | Hiển thị QR qua chức năng quản trị riêng','Tên bàn hợp lệ và chưa trùng?','Tên trùng, ID không tồn tại hoặc xóa bàn còn quan hệ bị chặn.','Bàn có mã QR phục vụ đọc ngữ cảnh; không xem QR là mã đăng nhập quản trị.','Ảnh báo cáo không công khai token QR thực tế, chỉ chụp màn hình danh sách không mở mã bí mật.')
add(A,'Quản lý nguyên liệu và đơn vị','AdminService.createMaterial','AdminController',inv,'Material; Stock','Khai báo nguyên liệu THO/SOCHE và các thuộc tính sử dụng trong quản lý kho.','Tên, type, unit và dữ liệu MaterialRequest.','ADMIN; nguyên liệu chưa trùng và các ràng buộc hợp lệ.','Kiểm tra thông tin nguyên liệu | Chuẩn hóa trường dữ liệu | Lưu Material | Tạo/đảm bảo tồn theo chính sách service | Trả MaterialResponse','Nguyên liệu và loại/đơn vị hợp lệ?','Tên trùng, định dạng không hợp lệ hoặc không tồn tại khi sửa.','Nguyên liệu có thể dùng trong định mức và chứng từ kho.','Không tự tạo bảng biến thể ngoài mô hình hoặc các thuộc tính không tồn tại trong Entity.')
add(A,'Quản lý định mức sơ chế','AdminService.createPreparationRecipe','AdminController',inv,'PreparationRecipe; PreparationRecipeItem; Material','Định nghĩa cấu trúc đầu vào/đầu ra cho mẻ sơ chế.','outputMaterialId, standardOutputQuantity, inputs và active.','ADMIN; thành phẩm và nguyên liệu đầu vào đúng loại; lượng dương.','Kiểm tra thành phẩm sơ chế | Kiểm tra sản lượng chuẩn | Duyệt từng đầu vào và loại bỏ cấu hình sai | Tạo PreparationRecipe cùng các item | Lưu và trả cấu hình','Đầu ra, đầu vào và định lượng hợp lệ?','Thiếu nguyên liệu, loại không phù hợp, lặp đầu vào hoặc sản lượng không dương.','Bếp sử dụng định mức được lưu thay vì công thức tự bịa trong giao diện.','Sửa/xóa được kiểm tra bằng các method tương ứng; giữ dấu vết chứng từ mẻ đã tạo.')
add(A,'Điều chỉnh kho tổng có lý do','InventoryService.adjustRawMaterialStock','InventoryController',inv,'Stock; Material; StockMovement','Hiệu chỉnh tồn hoặc giá vốn của nguyên liệu thô theo quyền quản trị.','materialId, tồn thực tế/giá nhập, threshold và lý do điều chỉnh.','ADMIN; tồn KHO của nguyên liệu THO tồn tại.','Kiểm tra loại THO và vị trí KHO | Khóa Stock và đối chiếu giá trị mới | Bắt buộc lý do khi tồn/giá thay đổi | Cập nhật tồn, giá vốn và ngưỡng | Ghi movement/audit, lan truyền giá vốn khi cần','Giá trị không âm và có lý do?','Nguyên liệu không tồn tại, loại sai, thiếu lý do hoặc giá trị âm.','Điều chỉnh có thể truy vết, không thay đổi số liệu ngầm.','Chức năng không đồng nghĩa chuyển tự do tồn của mọi chi nhánh; schema kho hiện tại theo nguyên liệu/vị trí.')
add(A,'Thiết lập ngưỡng cảnh báo tồn','InventoryService.configureThreshold','InventoryController',inv,'Stock; Material','Đặt mức tồn tối thiểu cho cảnh báo vận hành.','materialId, location và threshold.','ADMIN theo PreAuthorize.','Tìm dòng tồn theo khóa nguyên liệu/vị trí | Kiểm tra dữ liệu request | Gán ngưỡng mới | Lưu Stock | Danh sách tồn tính cảnh báo ở lần đọc sau','Dòng tồn có tồn tại?','Không tìm thấy dòng tồn hoặc threshold không hợp lệ theo DTO.','Thay ngưỡng không cộng/trừ số lượng đang có.','Thông báo tồn thấp là tín hiệu vận hành, không tự tạo phiếu nhập hoặc mẻ sơ chế.')
add(A,'Quản lý đơn và trạng thái thanh toán','OrderService.getOrderWorkSummary','OrderController','templates/admin/orders.html; static/js/admin/admin.js','Order; Invoice; Payment; RefundRequest; CancellationRequest','Tổng hợp các nhóm công việc cần xử lý cho quầy/quản trị.','Actor và các bộ lọc danh sách liên quan.','ADMIN hoặc CASHIER theo endpoint; dữ liệu đọc được theo scope service.','Lấy đơn và lọc phạm vi | Xác định các nhóm confirm/cooking/completed | Kiểm tra Payment và notice chuyển khoản | Ghép yêu cầu hủy/hoàn | Trả số lượng và tập hành động chờ','Đơn thuộc nhóm công việc nào?','Không có quyền hoặc dữ liệu không khớp; không suy ra PAID chỉ từ trạng thái hoàn thành.','Các ô tổng hợp hỗ trợ xử lý, chưa tự quyết định đơn hay tiền.','Trang admin/orders có route và template; không tạo một dashboard chuỗi dựa trên số liệu không được truy vấn.')
add(A,'Phê duyệt hoàn tiền chuyển khoản','RefundService.decideRefund','CancellationController','templates/admin/orders.html; static/js/admin/admin.js','RefundRequest; BusinessAudit','Phê duyệt/từ chối hồ sơ hoàn tiền ngân hàng theo quy trình lưu trong service.','refundId, approve, decisionReason và adminId.','ADMIN; yêu cầu hoàn còn trạng thái được xử lý.','Khóa yêu cầu hoàn | Kiểm tra trạng thái đã xử lý | Lưu quyết định phê duyệt hoặc từ chối | Ghi thông tin quản trị và thời gian | Audit và phát sự kiện','Yêu cầu còn đủ điều kiện quyết định?','Không tồn tại, đã quyết định hoặc trạng thái không cho thao tác.','Chứng từ phản ánh quyết định; việc thực chi theo nhánh source tương ứng.','Không khẳng định có API ngân hàng chuyển tiền tự động. recordRefundPayment là bước riêng cho yêu cầu đã duyệt.')
add(A,'Cấu hình cửa hàng, ngân hàng và giảm giá chung','SettingsService.updateSettings','SettingsController','templates/admin/settings.html; static/js/admin/admin.js','GlobalSettings; BusinessAudit','Quản lý tên/địa chỉ cửa hàng, tài khoản nhận tiền và kiểu giảm giá chung.','SettingsDto.UpdateSettingsRequest; actor sửa.','ADMIN; mức giảm hợp lệ theo kiểu phần trăm hoặc số tiền.','Lấy GlobalSettings | Kiểm tra loại/mức giảm | Cập nhật thương hiệu, địa chỉ và dữ liệu ngân hàng | Lưu modifiedBy/modifiedAt | Phát SETTINGS_CHANGED sau commit','Mức giảm và dữ liệu cấu hình hợp lệ?','Giảm cố định âm hoặc dữ liệu ngoài điều kiện service.','Đơn mới dùng chính sách mới; hóa đơn cũ giữ snapshot giảm giá.','Báo cáo không chép số tài khoản thật, secret VNPAY hay mật khẩu SMTP vào bảng cấu hình.')
add(A,'Thống kê doanh thu theo khoảng thời gian','ReportService.getRevenueReport','ReportController','templates/admin/reports.html; static/js/admin/dashboard.js','Invoice; Payment; Order; RefundRequest','Tổng hợp số liệu doanh thu theo truy vấn đã được triển khai.','fromDate/toDate theo LocalDate.','ADMIN; bộ lọc ngày được chuẩn hóa trong service.','Xác định khoảng thời gian | Truy vấn dữ liệu tiền/hóa đơn theo thời điểm phù hợp | Tính các chỉ tiêu được DTO định nghĩa | Nhóm và sắp dữ liệu | Trả RevenueReportView','Khoảng ngày có dữ liệu?','Bộ lọc sai hoặc kết quả rỗng; không trình bày số demo như doanh thu kinh doanh thật.','Giao diện báo cáo đọc được thống kê từ DB.','Cần phân biệt ngày đặt, paidAt và hoàn tiền theo truy vấn; không đồng nhất mọi đơn tạo ra thành doanh thu đã thu.')
add(A,'Dashboard đơn, sản phẩm và cảnh báo','ReportService.getDashboard','ReportController','templates/admin/reports.html; static/js/admin/dashboard.js','Order; OrderItem; Payment; Stock; Material','Tổng hợp báo cáo đơn, top sản phẩm, hao hụt và cảnh báo vận hành.','fromDate/toDate và actor quản trị.','ADMIN; database có chứng từ để thống kê.','Chuẩn hóa phạm vi ngày | Lấy summary và doanh thu từng ngày | Lấy trạng thái đơn và top sản phẩm | Lấy hao hụt nguyên liệu và cảnh báo tồn | Trả DashboardResponse','Có dữ liệu và chỉ tiêu tương ứng?','Không có quyền hoặc số liệu rỗng theo thời gian lọc.','Không tạo dữ liệu kinh doanh giả để làm đầy biểu đồ.','Chụp demo phản ánh bộ dữ liệu thử nghiệm đã đánh dấu, không phải chứng minh KPI vận hành thật.')
add(A,'Đổi logo và ảnh đại diện','ProductImageService.uploadLogoImage','SettingsController','templates/admin/settings.html; templates/profile.html','GlobalSettings; Account','Quản lý ảnh thương hiệu bằng pipeline kiểm tra và cleanup file ngoài hệ thống.','MultipartFile; logo hoặc avatar có endpoint/method riêng.','Có quyền tương ứng và Cloudinary đã cấu hình.','Kiểm tra nội dung ảnh | Upload ảnh mới | Cập nhật URL/publicId trong bản ghi | Đăng ký dọn file nếu rollback | Dọn ảnh cũ sau commit khi cần','Ảnh và dịch vụ upload hợp lệ?','Cấu hình thiếu, tệp không phù hợp hoặc upload lỗi.','Ảnh mới dùng cho lần hiển thị sau; không làm lộ API key trong response.','uploadAvatarImage xác minh tài khoản; báo cáo chỉ trích mã, không thử upload bằng credentials thật.')
add(V,'Tạo và chỉnh sửa cơ sở trong phân hệ mở rộng','MarketService.createShop','MarketController',portal,'Shop; Account','Quản lý thông tin cơ sở theo quan hệ chủ sở hữu đang có trong code.','Tên, địa chỉ, area và tọa độ tùy chọn.','Chỉ CUSTOMER/VENDOR/ADMIN được tạo theo service; cơ sở mới cần kích hoạt theo quyền quản trị.','Lấy Account có khóa | Kiểm tra vai trò được tạo | Tạo Shop gắn owner | Nếu CUSTOMER thì chuyển VENDOR | Lưu Shop và trả ShopView','Vai trò được phép tạo cơ sở?','Vai trò không được phép, dữ liệu địa chỉ/tọa độ không hợp lệ.','Shop giữ owner và trạng thái hoạt động theo cấu hình.','Đây là module mở rộng còn hiện diện; không khẳng định chỉ có bốn role khi Role.java còn VENDOR/MANAGER/SHIPPER.')
add(V,'Phân công quản lý, thu ngân và bếp theo cơ sở','MarketService.assignManager','MarketController',portal,'Shop; Account; ShopManager (join table)','Gắn tài khoản nhân viên vào cơ sở để kiểm tra phạm vi các đơn mới.','shopId, accountId, enabled.','ADMIN; tài khoản đích là MANAGER, CASHIER hoặc KITCHEN.','Kiểm tra ADMIN | Tìm Shop trong scope | Kiểm tra vai trò tài khoản đích | Thêm/bỏ khỏi tập managers | JPA đồng bộ bảng nối ShopManager','Vai trò nhân viên thuộc tập cho phép?','Không có quyền, không có tài khoản hoặc role không được phân công.','OrderBranchService.canAccess đọc quan hệ này khi lọc và thao tác đơn.','Tên bảng nối là ShopManager nhưng được tái sử dụng cho quyền quầy/bếp; không tạo bảng BranchStaff không tồn tại.')
add(V,'Quản lý menu và tồn bán theo cơ sở','MarketService.saveProduct','MarketController',portal,'Shop; Category; Product','Cập nhật biến thể món thuộc Shop và lượng tồn bán của module mở rộng.','ProductInput gồm danh mục, tên/size, giá, menuCode, stock và version.','VENDOR là owner, MANAGER được phân công hoặc ADMIN; Category thuộc đúng Shop.','Xác minh scope | Tìm/tạo Product thuộc cơ sở | So khớp version với catalogVersion | Kiểm tra danh mục và menuCode | Lưu giá/tồn/trạng thái và trả ProductView','Phạm vi và version còn khớp?','Khác cơ sở, danh mục sai hoặc dữ liệu đã đổi ở phiên khác.','Menu có bản ghi theo Shop; checkout POS ánh xạ menuVariantIdentity để lấy đúng giá.','Không xem deliveryStock là bằng chứng toàn bộ Stock nguyên liệu đã được phân vùng chi nhánh; hai module có mô hình riêng.')
add(V,'Quản lý mã khuyến mãi qua API cơ sở','MarketService.saveVoucher','MarketController',portal,'Voucher; Shop; Account','Tạo các điều kiện ưu đãi còn được backend hỗ trợ.','Code, số tiền giảm, đơn tối thiểu, startsAt/endsAt, usageLimit, perAccountLimit, active.','Scope quản trị/cơ sở hợp lệ.','Kiểm tra phạm vi Shop | Kiểm tra thời gian bắt đầu/kết thúc | Chuẩn hóa code và kiểm tra trùng | Lưu các giới hạn lượt dùng | Trả VoucherView','Ngày hết hạn và mã hợp lệ?','Hết hạn trước bắt đầu, code trùng hoặc thiếu quyền.','Mã có dữ liệu điều kiện sử dụng trong DB.','Ô nhập mã đã bỏ khỏi checkout mới theo yêu cầu; có API/model không đồng nghĩa khách hiện dùng được ô nhập mã trên giao diện.')
add(V,'Hạn chế khách mua tại một cơ sở','MarketService.customerAccess','MarketController',portal,'ShopCustomerAccess; Shop; Account','Lưu chính sách chặn mua cục bộ thay vì khóa toàn bộ Account.','shopId, accountId và enabled.','VENDOR/MANAGER/ADMIN có scope hợp lệ.','Xác minh scope | Tìm Account khách và quan hệ mua | Cập nhật cờ blocked | Lưu ShopCustomerAccess | Các lệnh quote/tạo đơn kiểm tra assertCustomer','Có quyền đối với cơ sở?','Actor không thuộc scope hoặc tài khoản không tồn tại.','Hạn chế chỉ áp dụng tại Shop; trạng thái đăng nhập toàn hệ thống không tự đổi.','Khác với active=false do ADMIN khóa tài khoản; hai cơ chế không được viết lẫn trong báo cáo.')
add(V,'Tra cứu đơn giao hàng lịch sử theo phạm vi','MarketService.orders','MarketController','templates/customer/marketplace.html; '+portal,'DeliveryOrder; DeliveryLine; Shop; Account','Bảo toàn truy cập dữ liệu của module giao hàng đã tồn tại.','shopId tùy actor; tài khoản hiện tại.','Đã đăng nhập; phạm vi được tính theo owner/manager/khách/shipper trong service.','Xác định actor và scope | Lấy danh sách DeliveryOrder | Lọc theo quyền/cơ sở | Ánh xạ line, tiền và trạng thái | Trả lịch sử cho màn hình','Actor có dữ liệu trong scope?','Không có quyền hoặc không có lịch sử.','Chỉ đọc các đơn cũ; không biến thành quy trình giao hàng mới của khách.','MarketController.checkout hiện chủ động từ chối tạo đơn giao hàng. Các route quote/carrier và class cũ chưa bị xóa.',status='Module lịch sử/tương thích còn mã nguồn')
